// Synthetic browser fixture; no production API or messages.
import express from 'express';
import {resolve} from 'node:path';
const app=express();app.use(express.static(resolve('public'),{index:false}));
app.get('/',(req,res)=>res.type('html').send(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Automation activity preview</title><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/e2-theme.css"><link rel="stylesheet" href="/dashboard-theme.css"><style>body{margin:0;background:#f7fafb}.preview{max-width:1200px;margin:0 auto;padding:32px 24px}.preview>header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:28px}.preview h1{font-size:28px;margin:0 0 8px}.preview header p{margin:0;color:var(--muted);font-size:13px}.preview .fixture{font-size:11px;margin-bottom:20px;color:var(--muted)}@media(max-width:540px){.preview{padding:20px 16px}.preview h1{font-size:24px}}</style></head><body class="crm"><main class="preview"><p class="fixture">Design preview · sample data</p><header><div><h1>Automation activity</h1><p>Responses, bookings and follow-up workload</p></div><button class="btn ghost" id="refresh">Refresh</button></header><div id="root"></div></main><script type="module">
import {mountAutomationActivity} from '/automationActivity.js';
const base={id:'one',customer:'Alex Morgan',phone:'+13035550123',form_title:'Moving quote',version:3,status:'active',tags:[{name:'Moving'}],latest_response:'A Friday morning move would be ideal.',confirmed_bookings:0,cancelled_bookings:0,unresolved_handoffs:0,handoffs:0,next_run_at:'2026-10-13T15:00:00Z'};
const rows=[base,{...base,id:'two',customer:'Jamie Parker',phone:'+13035550124',status:'paused',latest_response:'Could someone call me to discuss the quote?',unresolved_handoffs:1,handoffs:1,tags:[]},{...base,id:'three',customer:'Taylor Reed',phone:'+13035550125',status:'completed',latest_response:'All confirmed, thank you!',confirmed_bookings:1}];
const report={reportingAt:'2026-10-12T20:35:00Z',timeZone:'America/Denver',from:'2026-09-13',to:'2026-10-12',forms:[{id:'moving',title:'Moving quote'}],templates:[],tags:[{id:'moving-tag',name:'Moving'}],rows,total:3,pageSize:25,canManage:false,activity:{accepted:128,delivered:124,responses:42,aiSent:36},outcomes:{linkedBookings:18,handoffs:5},funnel:{contacted:58,responded:32,booked:18,cancelled:2,responseRate:55,conversionRate:31},directFunnel:{contacted:12,responded:7,booked:3,cancelled:0,responseRate:58,conversionRate:25},workload:{active:16,quiet:4,paused:2,aiPaused:1,unresolvedHandoffs:3},definitions:{activity:'Messages counted within the selected dates. Provider acceptance does not guarantee delivery.',cohort:'Enquiries first contacted in the selected dates.',conversion:'Outcomes include later responses and currently confirmed bookings.',workload:'Current workload, independent of the selected dates.'}};
async function apiFetch(path){const u=new URL(path,location.origin),q=u.searchParams;let body;
if(u.pathname.endsWith('/report')){let filtered=rows.filter(r=>(!q.get('search')||r.customer.toLowerCase().includes(q.get('search').toLowerCase()))&&(!q.get('status')||r.status===q.get('status'))&&(!q.get('quick')||q.get('quick')!=='paused'||r.status==='paused'));body={...report,rows:filtered,total:filtered.length};}
else if(u.pathname.endsWith('/timeline'))body={enquiry:rows.find(r=>r.id===q.get('runId')),handoffs:[],bookings:[],canManage:false,events:[{kind:'submission',occurred_at:report.reportingAt,details:{}},{kind:'customer_response',occurred_at:report.reportingAt,details:{body:'Thanks for your help.'}}]};
else body={rows:[],total:0};return Response.json(body);}
let dispose;async function mount(){dispose?.();dispose=await mountAutomationActivity(document.querySelector('#root'),{apiFetch,embedded:true,identity:'layout-fixture',isCurrent:()=>true,onConversation(){},onForm(){},onBookings(){},onHandoffs(){}});}document.querySelector('#refresh').onclick=mount;mount();
</script></body></html>`));
app.listen(8190,'127.0.0.1',()=>console.log('Activity preview http://127.0.0.1:8190'));

